// Auto-load function to populate owned cards across all decks
function loadOwnedCards() {
    if (typeof decks === 'undefined') {
        console.warn('Decks not loaded yet');
        return;
    }

    function parseCardEntry(entry) {
        const match = entry.match(/^(\d+)\s+(.+)$/);
        if (match) {
            return { quantity: parseInt(match[1]), name: match[2] };
        }
        return { quantity: 1, name: entry };
    }

    let totalUpdated = 0;

    decks.forEach(deck => {
        const ownedCardsObj = {};

        const processCards = (cardList) => {
            if (!cardList) return;

            cardList.forEach(cardEntry => {
                const parsed = parseCardEntry(cardEntry);
                const ownedQty = ownedCardsCollection[parsed.name] || 0;

                if (ownedQty > 0) {
                    if (ownedQty >= parsed.quantity) {
                        ownedCardsObj[cardEntry] = true;
                    } else {
                        ownedCardsObj[cardEntry] = ownedQty;
                    }
                    totalUpdated++;
                }
            });
        };

        processCards(deck.mainDeck);
        processCards(deck.extraDeck);

        localStorage.setItem(`ownedCards_${deck.id}`, JSON.stringify(ownedCardsObj));
    });

    console.log(`✅ Owned cards loaded automatically: ${totalUpdated} card entries marked`);
}

// Auto-execute when page loads
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', loadOwnedCards);
} else {
    loadOwnedCards();
}
